// ============================================================
// js/supabase-client.js
// Initialises the Supabase JS client for the entire site.
//
// KEY POINTS:
//   - window.SUPABASE_URL and window.SUPABASE_ANON_KEY come from
//     js/config.js, which is generated by the build script from
//     environment variables and is .gitignore'd.
//   - The anon key is the PUBLIC key — by design it is safe to use
//     in browser code. All security is enforced by Supabase Row Level
//     Security (RLS) policies on the database.
//   - The secret service_role key is NEVER used in frontend code.
//
// LOAD ORDER (in every HTML page that needs the database):
//   js/config.js  →  supabase CDN script  →  js/supabase-client.js
//   →  js/auth.js  →  js/db-schemes.js / js/db-quiz.js
// ============================================================

(function () {
  'use strict';

  const url  = window.SUPABASE_URL  || '';
  const anon = window.SUPABASE_ANON_KEY || '';

  if (!url || !anon) {
    console.warn(
      '[GramFin] Supabase config not found. ' +
      'Run: node scripts/generate-config.js (or set env vars on Vercel). ' +
      'The site will work with local data until the DB is connected.'
    );
    window.gramfinDB = null;
    return;
  }

  if (!window.supabase) {
    console.error('[GramFin] Supabase JS library not loaded. Check the CDN <script> tag.');
    window.gramfinDB = null;
    return;
  }

  try {
    window.gramfinDB = window.supabase.createClient(url, anon, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true
      }
    });
    console.log('[GramFin] ✅ Supabase client ready');
  } catch (err) {
    console.error('[GramFin] Failed to initialise Supabase:', err);
    window.gramfinDB = null;
  }
})();
